"""PostgreSQL persistence for the shared scheduler."""

from contextlib import contextmanager

import psycopg
from psycopg import errors
from psycopg.rows import dict_row

from .store import SCHEMA, backfill_metrics


SCHEDULER_LOCK = 168069402
POSTGRES_SCHEMA = SCHEMA.replace(" INTEGER", " BIGINT").replace(
    "    id TEXT PRIMARY KEY,\n    team", "    id TEXT PRIMARY KEY,\n    rowid BIGINT GENERATED BY DEFAULT AS IDENTITY,\n    team"
)


class StorageUnavailable(Exception):
    pass


class Row(dict):
    def __getitem__(self, key):
        if isinstance(key, int):
            return tuple(self.values())[key]
        return super().__getitem__(key)


def row_factory(cursor):
    factory = dict_row(cursor)
    return lambda values: Row(factory(values))


class Session:
    def __init__(self, connection):
        self.connection = connection

    def execute(self, statement, values=()):
        return self.connection.execute(statement.replace("?", "%s"), values)

    def executemany(self, statement, values):
        with self.connection.cursor() as cursor:
            cursor.executemany(statement.replace("?", "%s"), values)


class PostgresStore:
    def __init__(self, dsn, initial_time):
        self.dsn = dsn
        with self.session(write=True) as db:
            for statement in POSTGRES_SCHEMA.split(";"):
                if statement.strip():
                    db.execute(statement)
            db.execute("ALTER TABLE jobs ADD COLUMN IF NOT EXISTS failure_reason TEXT")
            db.execute(
                "INSERT INTO clock(id, now) VALUES (1, ?) ON CONFLICT (id) DO NOTHING",
                (initial_time,),
            )
            backfill_metrics(db)

    def reclaim_archived_space(self):
        # PostgreSQL autovacuum reclaims dead tuples after archival deletes.
        pass

    @contextmanager
    def session(self, write=False):
        try:
            with psycopg.connect(self.dsn, row_factory=row_factory, connect_timeout=5) as connection:
                if write:
                    connection.execute("SET LOCAL lock_timeout = '5s'")
                    connection.execute("SELECT pg_advisory_xact_lock(%s)", (SCHEDULER_LOCK,))
                else:
                    connection.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY")
                connection.execute("SET LOCAL statement_timeout = '30s'")
                yield Session(connection)
        except (psycopg.OperationalError, errors.LockNotAvailable, errors.QueryCanceled) as exc:
            raise StorageUnavailable("PostgreSQL is temporarily unavailable") from exc
